// Parallel: all copies must fail.  Series: every tier must be up.
function parallel(a, n) { return 1 - Math.pow(1 - a, n); }
function r(x, d) { return Number(x.toFixed(d)); }

const lb = parallel(0.999, 2);   // 2 load balancers
const app = parallel(0.99, 3);   // 3 app servers
const db = 0.9995;               // 1 database
const total = lb * app * db;     // tiers in series: multiply
console.log("LB tier  =", lb.toFixed(6));
console.log("App tier =", app.toFixed(6));
console.log("DB       =", db);
console.log("Total    =", total.toFixed(6));
console.log("Downtime hours/year =", ((1 - total) * 8760).toFixed(2));
// With a standby DB the weakest link improves a lot
const total2 = lb * app * parallel(0.9995, 2);
console.log("With DB standby =", total2.toFixed(6), " hours/year =", ((1 - total2) * 8760).toFixed(2));

