public class Main {
    // Parallel: all copies must fail.  Series: every tier must be up.
    static double parallel(double a, int n) { return 1 - Math.pow(1 - a, n); }
    static String r(double x, int d) { return String.format("%." + d + "f", x); }

    public static void main(String[] args) {
        double lb = parallel(0.999, 2);   // 2 load balancers
        double app = parallel(0.99, 3);   // 3 app servers
        double db = 0.9995;               // 1 database
        double total = lb * app * db;     // tiers in series: multiply
        System.out.println("LB tier  = " + r(lb, 6));
        System.out.println("App tier = " + r(app, 6));
        System.out.println("DB       = " + db);
        System.out.println("Total    = " + r(total, 6));
        System.out.println("Downtime hours/year = " + r((1 - total) * 8760, 2));
        // With a standby DB the weakest link improves a lot
        double total2 = lb * app * parallel(0.9995, 2);
        System.out.println("With DB standby = " + r(total2, 6) + "  hours/year = " + r((1 - total2) * 8760, 2));
    }
}

