using System;
using System.Globalization;

class Program
{
    // Parallel: all copies must fail.  Series: every tier must be up.
    static double Parallel(double a, int n) { return 1 - Math.Pow(1 - a, n); }
    static string R(double x, int d) { return x.ToString("F" + d, CultureInfo.InvariantCulture); }

    static void Main()
    {
        double lb = Parallel(0.999, 2);   // 2 load balancers
        double app = Parallel(0.99, 3);   // 3 app servers
        double db = 0.9995;               // 1 database
        double total = lb * app * db;     // tiers in series: multiply
        Console.WriteLine("LB tier  = " + R(lb, 6));
        Console.WriteLine("App tier = " + R(app, 6));
        Console.WriteLine("DB       = " + db.ToString(CultureInfo.InvariantCulture));
        Console.WriteLine("Total    = " + R(total, 6));
        Console.WriteLine("Downtime hours/year = " + R((1 - total) * 8760, 2));
        // With a standby DB the weakest link improves a lot
        double total2 = lb * app * Parallel(0.9995, 2);
        Console.WriteLine("With DB standby = " + R(total2, 6) + "  hours/year = " + R((1 - total2) * 8760, 2));
    }
}
